fn longest<'a>(left: &'a str, right: &'a str) -> &'a str {
    if left.len() >= right.len() { left } else { right }
}

fn main() {
    {
        let first = String::from("borrowed view");
        let second = String::from("Rust");
        let result = longest(&first, &second);
        println!("{result}");
    }
}
